
/* 宽度上限 = 整卡 2/3，居中；高度上限见 --portrait-cap（320px） */
.portrait {
  position: relative;
  width: 100%;
  max-width: 66.666%;
  margin: 0 auto;
  overflow: hidden;
  border-radius: 14px;
  background: var(--c-panel-inner);
  border: 1px solid var(--c-border-soft);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.06);
}

.backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: blur(22px) brightness(1.02) saturate(1.15);
  transform: scale(1.15);
}

.main {
  position: relative;
  display: block;
  width: 100%;
  max-height: var(--portrait-cap);
  object-fit: contain;
}

.silhouette {
  width: 100%;
  aspect-ratio: 3 / 4;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1.5px dashed var(--c-border);
  border-radius: 14px;
  color: var(--c-text-faint);

  svg {
    width: 60px;
    height: 80px;
  }

  span {
    font-size: 0.78rem;
  }
}

.pool-badge {
  position: absolute;
  top: 8px;
  left: 8px;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.7rem;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid var(--c-border);
  color: var(--c-text-muted);
  backdrop-filter: blur(6px);

  &.nsfw {
    background: var(--c-danger-bg);
    border-color: var(--c-danger);
    color: var(--c-danger-text);
  }
}

.actions {
  position: absolute;
  right: 8px;
  bottom: 8px;
  display: flex;
  gap: 6px;

  button {
    padding: 4px 11px;
    border: 1px solid var(--c-border);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.9);
    color: var(--c-text);
    font-size: 0.75rem;
    font-weight: 500;
    cursor: pointer;
    backdrop-filter: blur(6px);

    &:active {
      transform: scale(0.95);
    }
  }
}
