
/* 一体化卡片：顶栏 / 人物页 / 心声 全部同宽相连。
   背景跟随当前人物主题色：低饱和同色系（color-mix 调色），不支持时回退白 */
.status-card {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-surface);
  background: color-mix(in srgb, var(--card-accent, #8e8e8e) 4%, #fbfbfc);
  border: 1px solid var(--c-border);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.05);
}

.empty-hint {
  padding: 18px 16px;
  text-align: center;
  color: var(--c-text-faint);
  font-size: 0.9rem;
}

.pages {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 8px 12px;
}

.page-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.page-viewport {
  flex: 1;
  min-width: 0;
}

.nav-btn {
  flex: none;
  width: 32px;
  height: 48px;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  background: var(--c-surface);
  color: var(--c-text-muted);
  font-size: 1.3rem;
  line-height: 1;
  cursor: pointer;
  touch-action: manipulation;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);

  &:active {
    transform: scale(0.94);
  }
}

.dots {
  display: flex;
  justify-content: center;
  gap: 8px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-border);
  cursor: pointer;
  transition: width 0.2s ease;

  &.active {
    width: 20px;
    border-radius: 4px;
  }
}

.page-fade-enter-active,
.page-fade-leave-active {
  transition:
    opacity 0.18s ease,
    transform 0.18s ease;
}

.page-fade-enter-from {
  opacity: 0;
  transform: translateX(12px);
}

.page-fade-leave-to {
  opacity: 0;
  transform: translateX(-12px);
}

@media (max-width: 480px) {
  .nav-btn {
    width: 36px;
    height: 54px;
  }
}
