
/* 无自有卡片壳：作为一体化卡片的一节，与顶栏等宽相连 */
.char-page {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px 10px 4px;
}

.header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex-wrap: wrap;
}

.presence-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}

.name {
  font-weight: 700;
  font-size: 1.08rem;
  letter-spacing: 0.01em;
}

.stage {
  color: var(--c-text-muted);
  font-size: 0.82rem;
}

.dep-label {
  margin-left: auto;
  color: var(--c-text-muted);
  font-size: 0.78rem;
}

.dep-track {
  width: 88px;
  height: 7px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--card-accent, #8e8e8e) 12%, #ececef);
  overflow: hidden;
  flex: none;
}

.dep-fill {
  display: block;
  height: 100%;
  border-radius: 4px;
  transition: width 0.25s ease;
}

.dep-value {
  font-size: 0.82rem;
  color: var(--c-text-muted);
  min-width: 2ch;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.cycle {
  padding: 3px 11px;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 500;
  background: var(--c-panel-inner);
  border: 1px solid var(--c-border-soft);
  color: var(--c-text-muted);
  flex: none;

  &.danger {
    background: var(--c-danger-bg);
    border-color: var(--c-danger);
    color: var(--c-danger-text);
  }
}

.voice-label {
  color: var(--c-text-faint);
  font-size: 0.75rem;
}

.voice-text {
  padding: 12px 14px;
  background: color-mix(in srgb, var(--card-accent, #8e8e8e) 7%, #f7f7f8);
  border-left: 3px solid;
  border-radius: 10px;
  color: var(--c-text);
  font-size: 0.92rem;
  line-height: 1.7;
  white-space: pre-wrap;
  word-break: break-word;
}

@media (max-width: 480px) {
  .dep-track {
    width: 66px;
  }

  .name {
    font-size: 1rem;
  }
}
